        changes = 0
        while left < right:
            if arr[left] != arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    if not arr:
        return 0

    total_changes = 0
    left = 0
    right = len(arr) - 1

    while left < right:
        if arr[left] != arr[right]:
            total_changes += changes_to_palindrome(left + 1, right)
            total_changes += changes_to_palindrome(left, right - 1)
            return total_changes
        left += 1
        right -= 1

    return total_changes

